const updateIntegration = `-- name: UpdateIntegration :one
UPDATE integrations
SET name = $1, enabled = $2, all_personas = $3, config = $4, events = $5,
    secret_enc = $6, secret_hint = $7, updated_at = $8
WHERE company_id = $9 AND id = $10
RETURNING id, company_id, kind, slug, name, enabled, all_personas, config, events, secret_enc, secret_hint, created_by_type, created_by_id, created_at, updated_at
`

type UpdateIntegrationParams struct {
	Name        string
	Enabled     bool
	AllPersonas bool
	Config      []byte
	Events      []string
	SecretEnc   string
	SecretHint  string
	Now         time.Time
	CompanyID   uuid.UUID
	ID          uuid.UUID
}

func (q *Queries) UpdateIntegration(ctx context.Context, arg UpdateIntegrationParams) (Integration, error) {
	row := q.db.QueryRow(ctx, updateIntegration,
		arg.Name,
		arg.Enabled,
		arg.AllPersonas,
		arg.Config,
		arg.Events,
		arg.SecretEnc,
		arg.SecretHint,
		arg.Now,
		arg.CompanyID,
		arg.ID,
	)
	var i Integration
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.Kind,
		&i.Slug,
		&i.Name,
		&i.Enabled,
		&i.AllPersonas,
		&i.Config,
		&i.Events,
		&i.SecretEnc,
		&i.SecretHint,
		&i.CreatedByType,
		&i.CreatedByID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
